def verified_guidance(hazard_level: str) -> dict[str, str]:
    normalized = {"HIGH": "CRITICAL", "MEDIUM": "MODERATE"}.get(hazard_level, hazard_level)
    return HAZARD_GUIDANCE.get(normalized, GENERAL_GUIDANCE)
